PROJECT = Path(__file__).resolve().parent
ARMS = ('JOINT', 'SPLIT', 'CONDITIONAL')
sys.dont_write_bytecode = True


def read(path, default=None):
    path = Path(path)
    if not path.exists(): return default
    if path.is_symlink(): raise RuntimeError('拒绝读取重定向的状态文件')
    return json.loads(path.read_text(encoding='utf-8-sig'))


def clean(x):
    if isinstance(x, dict): return {str(k): clean(v) for k, v in x.items()}
    if isinstance(x, (list, tuple)): return [clean(v) for v in x]
    if hasattr(x, 'tolist'): return clean(x.tolist())
    if isinstance(x, float) and not math.isfinite(x): return None
    return x


def save(path, value):
    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)
    if path.is_symlink(): raise RuntimeError('拒绝覆盖重定向的输出文件')
    temporary = path.with_name(path.name + f'.pending_{os.getpid()}')
    temporary.write_text(json.dumps(clean(value), ensure_ascii=False, indent=2, allow_nan=False), encoding='utf-8')
    os.replace(temporary, path)


def digest(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as f:
        for b in iter(lambda: f.read(1024 * 1024), b''): h.update(b)
    return h.hexdigest()


def unpack(name, blob, wanted):
    raw = zlib.decompress(base64.b85decode(blob))
    if hashlib.sha256(raw).hexdigest() != wanted: raise RuntimeError('封存运行时hash不符')
    tree = ast.parse(raw.decode('utf-8-sig'))
    tree.body = [n for n in tree.body if not (isinstance(n, ast.If) and isinstance(n.test, ast.Compare)
                  and isinstance(n.test.left, ast.Name) and n.test.left.id == '__name__')]
    m = types.ModuleType(name); m.__file__ = str(Path(__file__).resolve()); sys.modules[name] = m
    exec(compile(tree, '<' + name + '>', 'exec'), m.__dict__)
    # 动态封存模块没有独立可导入文件；并行环境必须按值传递，不能让子进程猜模块路径。
    import cloudpickle
    cloudpickle.register_pickle_by_value(m)
    return m


def tasks():
    rng = random.Random(20261102); result = []
    for seed in (1901, 1902, 1903, 1904):
        order = list(ARMS) + ['STIN_ON', 'STIN_OFF']; rng.shuffle(order)
        for arm in order:
            result.append(dict(id=f'CORE__E1__K3__J3__{arm}__s{seed}', stage='CORE_JOINT',
                environment='E1', k=3, fleet=12, seed=seed, arm=arm, credit_arm=arm if arm in ARMS else 'JOINT',
                stin_mode=arm.removeprefix('STIN_') if arm.startswith('STIN_') else 'PLAIN',
                control='J3', reward_mode='PT_POST', time_mode='RAW', variant='M0_BASE',
                method='J3__M0_BASE', timing=True, batch=True, network='TRANSFORMER', gamma=.99,
                run_order=len(result) + 1))
    for seed in (1901, 1902, 1903, 1904):
        result.append(dict(id=f'ANCHOR__E1__K3__LQ__JOINT__s{seed}', stage='MATCHED_SINGLE',
            environment='E1', k=3, fleet=12, seed=seed, arm='JOINT', credit_arm='JOINT',
            stin_mode='PLAIN',
            control='LQ', reward_mode='PT_POST', time_mode='RAW', variant='M0_BASE',
            method='SINGLE__M0_BASE', timing=True, batch=True, network='TRANSFORMER', gamma=.99,
            run_order=len(result) + 1))
    if len(result) != 24 or len(result) * STEPS != PLANNED_STEPS or STEPS % 20480:
        raise AssertionError('矩阵和完整rollout预算不一致')
    return result


def clipped_surrogate(ratio, advantage, clip=.25):
    """纯标量参考，仅用于验证目标函数，不导入学习库。"""
    return -min(ratio * advantage, min(1 + clip, max(1 - clip, ratio)) * advantage)


def arm_loss_reference(arm, ratio_p, ratio_r, a_pre, old_pre, old_post, active_p=True, active_r=True):
    if arm == 'JOINT': return clipped_surrogate(ratio_p * ratio_r, a_pre)
    ar = a_pre + old_pre - old_post if arm == 'CONDITIONAL' else a_pre
    return (clipped_surrogate(ratio_p, a_pre) if active_p else 0.) + (clipped_surrogate(ratio_r, ar) if active_r else 0.)


def runtime():
    m = unpack('stage_credit_runtime', FROZEN_RUNTIME_B85, FROZEN_RUNTIME_SHA)
    m.ATTR_ROOT = ROOT_NAME; m.ATTR_STEPS = m.STEPS = m.FULL_ACTUAL_STEPS = STEPS
    m.ATTR_CAP = m.HARD_CAP = CAP; m.ATTR_PLANNED = PLANNED_STEPS
    m.VERSION = m.GAP_VERSION = VERSION; m.SCRIPT = Path(__file__).resolve()
    # 原始记录永远不改；新矩阵的状态文件统一采用原子落盘。
    m.save_json = save
    original_setup, original_manifest = m.gap_setup, m.attr_update_manifest
    def setup(task, root, phase):
        os.environ['UAM_STAGE_CREDIT_ARM'] = task['credit_arm']
        os.environ['UAM_STIN_MODE'] = task['stin_mode']
        os.environ['UAM_STIN_INIT_SEED'] = str(task['seed'])
        directory = original_setup(task, root, phase)
        install_stin_features(m)
        install_learner(m)
        return directory
    def manifest(folder, task):
        original_manifest(folder, task)
        path = Path(folder) / 'MODEL_MANIFEST.json'; record = read(path, {})
        record.update(version=VERSION, credit_arm=task['credit_arm'],
            main_question='同一既有状态与动作权限下，分头裁剪和阶段条件基线是否分别影响有限预算学习？',
            architecture='信用三臂同一普通Transformer；另两臂为公开源码STIN开关；所有Joint配相同训练期条件头',
            stin_mode=task['stin_mode'], stin_source_sha256=FROZEN_STIN_SHA,
            stin_boundary='公开源码mean聚合Transformer与同权重时序块旁路；非期刊CLS架构/原表4四格数字忠实复现',
            stin_compatibility='去掉SB3只读features_dim重复赋值；STIN两臂dropout固定0以对齐普通Transformer的PPO采样/更新概率合同；其余源结构不变',
            auxiliary='影子价值头只更新自身，不向actor或共享特征回传；JOINT/SPLIT拟合但不使用，CONDITIONAL使用采样前旧预测作飞机基线',
            information='不增加观测，不读未揭示未来，不补时间槽；飞机actor本来就读取dispatch态',
            gamma_warning='gamma=.99及GAE=.95固定；不是再次扫描折扣或时间特征',
            update_contract='每rollout原有400次actor更新；最多400次独立影子头更新，三种Joint臂同配额',
            estimator_boundary='条件基线不是COMA/HAPPO完整复现，不证明普通PPO无法学会，不自动成为论文主贡献',
            stage_target='条件头预测与pre-critic相同的GAE回报目标，不把它偷换成漏算当分钟奖励的另一个时刻价值',
            entrypoint_sha256=digest(__file__), actual_target_steps=STEPS)
        save(path, record)
    m.gap_setup = m.attr_setup = setup; m.attr_update_manifest = manifest
    return m


def stin_compatibility_tree():
    """仅去除公开源码对只读属性的重复赋值，其他节点原样保留。"""
    raw = zlib.decompress(base64.b85decode(FROZEN_STIN_B85))
    if hashlib.sha256(raw).hexdigest() != FROZEN_STIN_SHA: raise RuntimeError('STIN源码封存hash不符')
    tree = ast.parse(raw.decode('utf-8-sig')); removed = 0
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef) and node.name == '__init__':
            kept = []
            for line in node.body:
                if isinstance(line, ast.Assign) and len(line.targets) == 1 and isinstance(line.targets[0], ast.Attribute) and line.targets[0].attr == 'features_dim':
                    removed += 1
                else: kept.append(line)
            node.body = kept
    if removed != 1: raise RuntimeError('STIN兼容补丁范围与已核对源码不一致')
    return tree


def install_stin_features(m):
    if getattr(m, '_STAGE_STIN_PID', None) == os.getpid(): return
    exec(compile(stin_compatibility_tree(), '<author_stin_readonly_property_fix>', 'exec'), m.__dict__)
    OldFeatures = m.FullFeatures
    class ControlledFeatures(OldFeatures):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.stin_mode = os.environ.get('UAM_STIN_MODE', 'PLAIN')
            if self.stin_mode not in ('PLAIN', 'ON', 'OFF'): raise RuntimeError('未知STIN消融条件')
            if self.stin_mode != 'PLAIN':
                # 两臂先完整初始化相同STIN，不因少建一个模块而改变后续actor初始随机序列。
                with m.torch.random.fork_rng(devices=[]):
                    m.torch.random.default_generator.manual_seed(72003 + int(os.environ['UAM_STIN_INIT_SEED']))
                    self.temporal = m.TemporalTransformerExtractor(
                        m.gym.spaces.Box(-m.np.inf, m.np.inf, (6, self.schema.frame), m.np.float32),
                        features_dim=128, use_encoder=True, temporal_type='transformer',
                        n_layers=1, n_heads=2, ff_dim=256, aggregation='mean')
                    # 源默认dropout为.1；本轮两臂均固定为0，不把随机失活噪声混入STIN结构消融。
                    for layer in self.temporal.modules():
                        if isinstance(layer, m.torch.nn.Dropout): layer.p = 0.
                        if isinstance(layer, m.torch.nn.MultiheadAttention): layer.dropout = 0.
                # OFF仍保留六帧、逐帧编码、平均聚合、投影和已分配参数，只旁路位置编码及跨帧交互块。
                if self.stin_mode == 'OFF': self.temporal.temporal_type = 'none'
    ControlledFeatures.__module__ = m.__name__; ControlledFeatures.__qualname__ = 'ControlledFeatures'
    m.ControlledFeatures = m.FullFeatures = ControlledFeatures
    m._STAGE_STIN_PID = os.getpid()


def install_learner(m):
    if getattr(m, '_STAGE_CREDIT_PID', None) == os.getpid(): return
    import stable_baselines3
    if not stable_baselines3.__version__.startswith('2.9.'):
        raise RuntimeError('本轮核对的是SB3 2.9.x，请勿静默换训练库合同')
    th, np = m.torch, m.np
    from torch import nn
    from torch.nn import functional as F
    from stable_baselines3.common.utils import explained_variance
    OldPPO = m.FullPPO

    class StageCreditPPO(OldPPO):
        """源物理和actor不变，只替换预注册的PPO估计器；影子critic与策略梯度隔离。"""
        def _setup_model(self):
            super()._setup_model()
            requested = os.environ.get('UAM_STAGE_CREDIT_ARM', 'JOINT')
            if requested not in ARMS: raise RuntimeError('未知阶段信用实验臂')
            if hasattr(self, 'credit_arm') and self.credit_arm != requested: raise RuntimeError('模型实验臂与任务不一致')
            self.credit_arm = requested; k = self.policy.features_extractor.k
            # 不消耗原actor初始化/采样的随机数；所有Joint臂头结构和初值完全相同。
            with th.random.fork_rng(devices=[]):
                th.random.default_generator.manual_seed(71003 + int(self.seed or 0))
                head = nn.Sequential(nn.Linear(128 + k, 64), nn.Tanh(), nn.Linear(64, 1))
            self.dispatch_value = head.to(self.device)
            self.dispatch_optimizer = th.optim.Adam(self.dispatch_value.parameters(), lr=self.lr_schedule(1), eps=1e-5)
            self._credit_store = None

        def _excluded_save_params(self):
            return super()._excluded_save_params() + ['dispatch_value', 'dispatch_optimizer', '_credit_store']

        def _get_torch_save_params(self):
            states, variables = super()._get_torch_save_params()
            return states + ['dispatch_value', 'dispatch_optimizer'], variables

        def collect_rollouts(self, env, callback, rollout_buffer, n_rollout_steps):
            if self.use_sde: raise RuntimeError('本轮固定离散动作，不接受SDE合同变化')
            shape = (rollout_buffer.buffer_size, rollout_buffer.n_envs)
            store = {k: np.full(shape, np.nan, np.float32) for k in ('p_log', 'r_log', 'post_value')}
            self._credit_store = store; latest = {}; restored = []
            def patch(obj, name, wrapper):
                marker = object(); prior = obj.__dict__.get(name, marker); original = getattr(obj, name)
                setattr(obj, name, wrapper(original))
                restored.append((obj, name, prior, marker))
            def passenger_wrapper(original):
                def call(obs, deterministic=False):
                    action, value, probs = original(obs, deterministic)
                    latest['p_log'] = probs.gather(1, action[:, None]).flatten().clamp_min(1e-30).log()
                    latest['p'] = action
                    return action, value, probs
                return call
            def return_wrapper(original):
                def call(obs, passenger, deterministic=False):
                    latest.pop('features', None)
                    action, log_prob = original(obs, passenger, deterministic)
                    latest['r_log'] = log_prob
                    return action, log_prob
                return call
            def features_wrapper(original):
                def call(obs):
                    result = original(obs); latest['features'] = result.detach(); return result
                return call
            def add_wrapper(original):
                def call(obs, action, reward, episode_start, value, log_prob):
                    pos = rollout_buffer.pos; d = self.policy.features_extractor.schema
                    active = (np.asarray(obs)[:, d.return_mask] > .5).sum(-1) > 1
                    p_log, r_log = latest['p_log'], latest['r_log']
                    if not th.allclose(p_log + r_log, log_prob, atol=2e-6, rtol=2e-6):
                        raise RuntimeError('原联合log-prob与两头缓存不一致')
                    post = value.detach().flatten().clone()
                    if active.any():
                        if 'features' not in latest: raise RuntimeError('有效飞机选择缺少真实dispatch特征')
                        ids = F.one_hot(latest['p'].long(), self.policy.features_extractor.k).to(post.dtype)
                        # 仅用飞机采样前已生成的特征与已选乘客动作，不使用飞机动作或执行后状态。
                        with th.no_grad():
                            prediction = self.dispatch_value(th.cat([latest['features'], ids], -1)).flatten()
                        mask = th.as_tensor(active, device=self.device)
                        post[mask] = prediction[mask]
                    store['p_log'][pos] = p_log.detach().cpu().numpy()
                    store['r_log'][pos] = r_log.detach().cpu().numpy()
                    store['post_value'][pos] = post.cpu().numpy()
                    return original(obs, action, reward, episode_start, value, log_prob)
                return call
            patch(self.policy, 'sample_passenger', passenger_wrapper)
            patch(self.policy, 'return_with_logprob', return_wrapper)
            patch(self.policy.features_extractor, 'dispatch_features', features_wrapper)
            patch(rollout_buffer, 'add', add_wrapper)
            try:
                result = super().collect_rollouts(env, callback, rollout_buffer, n_rollout_steps)
                if result and any(not np.isfinite(v).all() for v in store.values()): raise RuntimeError('阶段缓存不完整')
                return result
            finally:
                for obj, name, prior, marker in reversed(restored):
                    if prior is marker: delattr(obj, name)
                    else: setattr(obj, name, prior)

        def train(self):
            if self.target_kl is not None or self.clip_range_vf is not None:
                raise RuntimeError('本轮未改变KL提前终止和值函数裁剪设置')
            if self._credit_store is None: raise RuntimeError('训练缺少采样前缓存')
            if self.device.type == 'cuda': th.cuda.synchronize(self.device)
            started = time.perf_counter(); self.policy.set_training_mode(True)
            self._update_learning_rate([self.policy.optimizer, self.dispatch_optimizer])
            clip = self.clip_range(self._current_progress_remaining); rb = self.rollout_buffer
            cached = {k: v.swapaxes(0, 1).reshape(-1) for k, v in self._credit_store.items()}
            if not rb.generator_ready:
                for name in ('observations', 'actions', 'values', 'log_probs', 'advantages', 'returns'):
                    rb.__dict__[name] = rb.swap_and_flatten(rb.__dict__[name])
                rb.generator_ready = True
            size = rb.buffer_size * rb.n_envs
            if not np.allclose(cached['p_log'] + cached['r_log'], rb.log_probs.flatten(), atol=2e-6, rtol=2e-6):
                raise RuntimeError('rollout展平顺序与阶段缓存不同')
            schema = self.policy.features_extractor.schema
            air_mask = (rb.observations[:, schema.return_mask] > .5).sum(-1) > 1
            p_mask = rb.observations[:, schema.passenger_active] > .5
            raw_adv = rb.advantages.flatten(); old_values = rb.values.flatten(); ret = rb.returns.flatten()
            conditional_adv = raw_adv + old_values - cached['post_value']
            old_pre_error = old_values[air_mask] - ret[air_mask]
            old_post_error = cached['post_value'][air_mask] - ret[air_mask]
            calibration = dict(step=int(self.num_timesteps), air_choices=int(air_mask.sum()), passenger_choices=int(p_mask.sum()),
                both_choices=int((air_mask & p_mask).sum()),
                old_pre_mse=float(np.mean(old_pre_error**2)) if air_mask.any() else None,
                old_post_mse=float(np.mean(old_post_error**2)) if air_mask.any() else None,
                shared_air_adv_variance=float(np.var(raw_adv[air_mask])) if air_mask.any() else None,
                conditional_air_adv_variance=float(np.var(conditional_adv[air_mask])) if air_mask.any() else None,
                note='使用采样时的旧预测衡量，不用同一批拟合后的误差冒充泛化；单侧无飞机样本时留空。')
            pg, vf, entropy_values, kls, clips, post_losses = [], [], [], [], [], []
            actor_updates = head_updates = 0
            for _ in range(self.n_epochs):
                indices = np.random.permutation(size)
                for start in range(0, size, self.batch_size):
                    ix = indices[start:start + self.batch_size]; data = rb._get_samples(ix)
                    actions = data.actions.long().flatten(); k = self.policy.features_extractor.k
                    ap, ar = actions // k, actions % k
                    latest = {}; feature_object = self.policy.features_extractor
                    original = feature_object.dispatch_features
                    had = 'dispatch_features' in feature_object.__dict__; previous = feature_object.__dict__.get('dispatch_features')
                    def capture(obs):
                        z = original(obs); latest['z'] = z; return z
                    feature_object.dispatch_features = capture
                    try:
                        p_logits, values = self.policy.passenger_parts(data.observations)
                        p_dist = th.distributions.Categorical(logits=p_logits)
                        r_dist = self.policy.return_distribution(data.observations, ap)
                    finally:
                        if had: feature_object.dispatch_features = previous
                        else: delattr(feature_object, 'dispatch_features')
                    values = values.flatten(); lp, lr = p_dist.log_prob(ap), r_dist.log_prob(ar)
                    active_p = data.observations[:, schema.passenger_active] > .5
                    active_r = (data.observations[:, schema.return_mask] > .5).sum(-1) > 1
                    a_pre = data.advantages
                    a_return = a_pre + data.old_values - th.as_tensor(cached['post_value'][ix], device=self.device)
                    # 三臂共用源优势的均值/尺度，不偷偷按稀疏飞机样本放大梯度。
                    if self.normalize_advantage and len(a_pre) > 1:
                        center, scale = a_pre.mean(), a_pre.std() + 1e-8
                        a_pre, a_return = (a_pre - center) / scale, (a_return - center) / scale
                    joint_log = lp + lr; joint_ratio = th.exp(joint_log - data.old_log_prob)
                    ratio_p = th.exp(lp - th.as_tensor(cached['p_log'][ix], device=self.device))
                    ratio_r = th.exp(lr - th.as_tensor(cached['r_log'][ix], device=self.device))
                    if actor_updates == 0 and not th.allclose(joint_log, data.old_log_prob, atol=1e-4, rtol=1e-4):
                        raise RuntimeError('更新前不能重建采样概率；检查STIN失活/归一化合同，不继续污染该格')
                    def clipped(ratio, advantage):
                        return -th.minimum(ratio * advantage, ratio.clamp(1 - clip, 1 + clip) * advantage)
                    if self.credit_arm == 'JOINT': policy_loss = clipped(joint_ratio, a_pre).mean()
                    else:
                        air_adv = a_return if self.credit_arm == 'CONDITIONAL' else a_pre
                        # 分母仍是全小批量，不因有效飞机动作稀疏而改变学习率或梯度权重。
                        policy_loss = (clipped(ratio_p, a_pre) * active_p + clipped(ratio_r, air_adv) * active_r).mean()
                    value_loss = F.mse_loss(data.returns, values)
                    entropy_loss = -(p_dist.entropy() + r_dist.entropy()).mean()
                    loss = policy_loss + self.ent_coef * entropy_loss + self.vf_coef * value_loss
                    if not bool(th.isfinite(loss)): raise RuntimeError('非有限PPO损失，保留失败格')
                    self.policy.optimizer.zero_grad(); loss.backward()
                    th.nn.utils.clip_grad_norm_(self.policy.parameters(), self.max_grad_norm)
                    self.policy.optimizer.step(); actor_updates += 1
                    if bool(active_r.any()):
                        if 'z' not in latest: raise RuntimeError('条件critic缺少当前dispatch特征')
                        head_input = th.cat([latest['z'][active_r].detach(), F.one_hot(ap[active_r], k).to(values.dtype)], -1)
                        if head_input.requires_grad: raise RuntimeError('影子critic意外连接了actor计算图')
                        prediction = self.dispatch_value(head_input).flatten()
                        post_loss = F.mse_loss(prediction, data.returns[active_r].detach())
                        self.dispatch_optimizer.zero_grad(); post_loss.backward()
                        th.nn.utils.clip_grad_norm_(self.dispatch_value.parameters(), self.max_grad_norm)
                        self.dispatch_optimizer.step(); head_updates += 1; post_losses.append(float(post_loss.detach()))
                    with th.no_grad():
                        log_ratio = joint_log - data.old_log_prob
                        kls.append(float(((th.exp(log_ratio) - 1) - log_ratio).mean()))
                        clips.append(float(((joint_ratio - 1).abs() > clip).float().mean()))
                    pg.append(float(policy_loss.detach())); vf.append(float(value_loss.detach())); entropy_values.append(float(entropy_loss.detach()))
                self._n_updates += 1
            expected = self.n_epochs * math.ceil(size / self.batch_size)
            if actor_updates != expected: raise RuntimeError('actor更新次数不符合冻结合同')
            if self.device.type == 'cuda': th.cuda.synchronize(self.device)
            row = dict(step=int(self.num_timesteps), sampling_seconds=getattr(self, '_min_sampling_seconds', 0.),
                update_seconds=time.perf_counter() - started, ppo_minibatches=actor_updates,
                dispatch_head_updates=head_updates, dispatch_head_loss=statistics.mean(post_losses) if post_losses else 0.,
                actor_receives_head_gradient=False, **{k:v for k,v in calibration.items() if k != 'step'})
            rpc = getattr(self, '_min_rpc', {})
            row.update(prepare_rpc_seconds=rpc.get('prepare_step', 0.), finish_rpc_seconds=rpc.get('finish_step', 0.),
                       reset_rpc_seconds=rpc.get('reset_selected', 0.))
            for key, value in row.items():
                if isinstance(value, (int, float)) and value is not None: self.logger.record('diagnosis/' + key, value)
            self.logger.record('train/entropy_loss', statistics.mean(entropy_values))
            self.logger.record('train/policy_gradient_loss', statistics.mean(pg)); self.logger.record('train/value_loss', statistics.mean(vf))
            self.logger.record('train/approx_kl', statistics.mean(kls)); self.logger.record('train/clip_fraction', statistics.mean(clips))
            self.logger.record('train/loss', float(loss.detach())); self.logger.record('train/n_updates', self._n_updates, exclude='tensorboard')
            self.logger.record('train/clip_range', clip)
            self.logger.record('train/explained_variance', explained_variance(rb.values.flatten(), rb.returns.flatten()))
            history = getattr(self, '_min_timing', []); history.append(row); self._min_timing = history
            if self._full_save_hook is not None: self._full_save_hook(self)

    StageCreditPPO.__module__ = m.__name__; StageCreditPPO.__qualname__ = 'StageCreditPPO'
    m.StageCreditPPO = m.FullPPO = StageCreditPPO; m._STAGE_CREDIT_PID = os.getpid()


def make_confirmation_bank(m, root, native):
    with (native / 'train_data/passengers_300.csv').open(encoding='utf-8-sig', newline='') as f:
        reader = csv.DictReader(f); fields = reader.fieldnames; rows = list(reader)
    if len(rows) != 300 or fields is None: raise RuntimeError('源需求合同不是300条记录')
    spatial = [k for k in fields if k.lower() not in ('id', 'person_id', 'time', 'timestamp', 'arrival_time', 'arrival', 'request_time')]
    bank = []
    for seed in (6501, 6502, 6503, 6504):
        od = [{k:r[k] for k in spatial} for r in rows]; random.Random(seed).shuffle(od)
        result = [dict(r, **v) for r, v in zip(rows, od)]
        stream = io.StringIO(newline=''); writer = csv.DictWriter(stream, fieldnames=fields); writer.writeheader(); writer.writerows(result)
        blob = stream.getvalue().encode('utf-8'); path = root / 'bank' / f'order_{seed}.csv'
        if path.exists() and path.read_bytes() != blob: raise RuntimeError('新确认顺序被改变')
        if not path.exists(): path.write_bytes(blob)
        bank.append(dict(name=f'order_{seed}', path=str(path), sha256=digest(path),
                         role='设计冻结后新条件重排确认；非新分布，不用于挑checkpoint或改超参数'))
    save(root / 'NEW_CONFIRMATION_BANK.json', bank)
    return bank


def state_fingerprint(env):
    s = env.scenario
    record = dict(time=int(s.time), waiting=list(s.waiting_decisions), finished=sorted(s.finished_ids),
        people=[(str(p.id),p.state,p.sub_state,float(p.current_timer or 0),str(p.origin_vertiport_id)) for p in s.persons.persons.values()],
        aircraft=[(str(e.id),e.state.name,str(e.current_vertiport_id),str(getattr(e,'target_vertiport_id','')),
                   tuple(e.passenger_ids),float(e.battery_kwh),float(e.remaining_time or 0)) for e in s._all_evtols.values()],
        queues={str(v):list(q.person_list) for v,q in s.vertiports.vertiport_list.items()})
    return hashlib.sha256(json.dumps(clean(record), sort_keys=True).encode()).hexdigest()


def rng_get(m): return random.getstate(), m.np.random.get_state(), m.torch.get_rng_state().clone()


def rng_set(m, value):
    random.setstate(value[0]); m.np.random.set_state(value[1]); m.torch.set_rng_state(value[2])


def is_absorbing_tail(env):
    s = env.scenario; remaining = len(set(s.persons.persons) - set(s.finished_ids))
    if s.time <= s.passenger_generation_end_time or not remaining or s.waiting_decisions: return False
    planes = list(s._all_evtols.values())
    if len(planes) != 12 or any(e.state.name != 'IDLE' or e.passenger_ids for e in planes): return False
    queues = [len(v.person_list) for v in s.vertiports.vertiport_list.values()]
    return sum(queues) == remaining and all(q < 4 for q in queues)


def quality_suffix(base, m, job, template, obs, model, norm, action, mode, rng):
    rng_set(m, rng); env = base.clone_env(template); current = obs.copy(); total = 0; first = None
    initial = set(env.scenario.persons.persons); focal = env.scenario.waiting_decisions[0] if env.scenario.waiting_decisions else None
    cohort = Counter(); phases = Counter(); points = {}; ticks = 0; tail = 0
    try:
        with m.torch.no_grad():
            while env.scenario.time < 601:
                remaining = set(env.scenario.persons.persons) - set(env.scenario.finished_ids)
                total += len(remaining); cohort['focal'] += int(focal in remaining)
                cohort['existing'] += len((remaining & initial) - {focal}); cohort['future'] += len(remaining - initial)
                if is_absorbing_tail(env): tail += len(remaining)
                for pid in remaining:
                    sub = str(env.scenario.persons.persons[pid].sub_state)
                    phase = 'ground' if sub == 'to_vertiport' else 'wait' if sub in ('arriver_vertiport', 'wait_uam') else 'flight' if sub == 'fly' else 'other'
                    phases[phase] += 1
                current, done, _, _ = base.advance(m, job, env, current, model, norm, mode, action if ticks == 0 else None)
                ticks += 1
                if ticks == 1: first = state_fingerprint(env)
                if ticks in (60, 120, 240): points[str(ticks)] = total
                if done: break
        if sum(cohort.values()) != total or sum(phases.values()) != total: raise RuntimeError('逐选择人时拆分不守恒')
        return dict(action=list(action), cost=total, cohorts=dict(cohort), points=points, first_post=first,
                    phases=dict(phases), absorbing_tail=tail, before_absorbing=total-tail,
                    remaining=len(set(env.scenario.persons.persons) - set(env.scenario.finished_ids)))
    finally: env.close()


def quality_eval(m, task, root, config, model, norm):
    folder = root / 'cells' / task['id']; marker = folder / 'DECISION_QUALITY.json'
    if marker.exists(): return
    base = unpack('stage_credit_clone', FROZEN_BASE_B85, FROZEN_BASE_SHA)
    private = dict(family='pt', task=task, root=str(root), run_root=str(root), out=str(folder))
    def check_pause(unused):
        if (root / 'STOP_REQUESTED').exists(): raise RuntimeError('本轮收到停止请求')
    base.check_pause = check_pause; rows = []; coverage = []
    for bank in config['sealed_bank'][:2]:
        for origin in ('own', 'common_ready'):
            env, obs = base.env_new(m, private, bank['path'], 123)
            trajectory = []; selected = []; index = 0; air_only = 0; counts = [0] * env.k
            mode = 'MODEL' if origin == 'own' else 'READY'
            try:
                with m.torch.no_grad():
                    while True:
                        check_pause(None); active = bool(env.scenario.waiting_decisions)
                        passenger_pick = active and index in (60, 180)
                        maybe_air = origin == 'own' and env.joint and not active and air_only < 2
                        template = base.clone_env(env) if passenger_pick or maybe_air else None
                        initial_obs = obs.copy(); rng = rng_get(m)
                        remaining = len(set(env.scenario.persons.persons) - set(env.scenario.finished_ids)); trajectory.append(remaining)
                        obs, done, actual, _ = base.advance(m, private, env, obs, model, norm, mode)
                        eligible_air = maybe_air and len([v for v in env._legal if v > .5]) > 1 and remaining >= 12
                        if template is not None:
                            if passenger_pick or eligible_air:
                                selected.append((template, initial_obs, rng, len(trajectory)-1,
                                                 'passenger' if passenger_pick else 'air_only', list(actual)))
                                if eligible_air: air_only += 1
                            else: template.close()
                        if active: counts[actual[0]] += 1; index += 1
                        if done: break
                coverage.append(dict(trace=bank['name'], origin=origin, passenger_states=sum(x[4]=='passenger' for x in selected),
                                     air_only_states=air_only, generated=len(env.scenario.persons.persons)))
                for template, current, rng, offset, event, original_action in selected:
                    before = state_fingerprint(template); rng_set(m, rng)
                    # 共同状态下先计算被测模型的实际首次动作，后续统一READY。
                    probe = base.clone_env(template)
                    try:
                        _,_,actual,_ = base.advance(m, private, probe, current.copy(), model, norm, 'MODEL')
                        model_first_post = state_fingerprint(probe)
                    finally: probe.close()
                    reference = [actual[0], actual[1] if template.joint else -1]; candidates = [reference]
                    p_values = range(env.k) if template.scenario.waiting_decisions else (0,)
                    for p in p_values:
                        probe = base.clone_env(template); rng_set(m, rng)
                        try:
                            pending = probe.prepare_step(p)
                            valid = [a for a,v in enumerate(pending[probe.schema.return_mask]) if v > .5]
                            for a in valid:
                                candidate = [p, a if template.joint else -1]
                                if candidate not in candidates: candidates.append(candidate)
                            probe.finish_step(valid[0])
                        finally: probe.close()
                    follow = 'MODEL' if origin == 'own' else 'READY'
                    branches = [quality_suffix(base,m,private,template,current,model,norm,a,follow,rng) for a in candidates]
                    ref = branches[0]; winner = min(branches,key=lambda r:(r['cost'],r['action']!=reference,tuple(r['action'])))
                    if ref['first_post'] != model_first_post: raise RuntimeError('强制参考动作不能复现真实首次转移')
                    if origin == 'own' and ref['cost'] != sum(trajectory[offset:]): raise RuntimeError('新模型参考分支后缀不一致')
                    if state_fingerprint(template) != before: raise RuntimeError('新模型分支污染原状态')
                    rows.append(dict(trace=bank['name'], origin=origin, event=event, time=int(template.scenario.time),
                        state_sha=before, reference=reference, winner=winner['action'], loss=ref['cost']-winner['cost'],
                        cohort_gain={k:ref['cohorts'].get(k,0)-winner['cohorts'].get(k,0) for k in ('focal','existing','future')},
                        phase_gain={k:ref['phases'].get(k,0)-winner['phases'].get(k,0) for k in ('ground','wait','flight','other')},
                        absorbing_tail_gain=ref['absorbing_tail']-winner['absorbing_tail'],
                        before_absorbing_gain=ref['before_absorbing']-winner['before_absorbing'],
                        reference_remaining=ref['remaining'], winner_remaining=winner['remaining'], branches=branches))
            finally:
                for v in selected: v[0].close()
                env.close()
    save(marker,dict(task=task,rows=rows,coverage=coverage,clone_reference_passed=True,new_training_transitions=0,
        note='同时覆盖乘客事件及无新乘客的有效调机；零样本明确报告。局部损失不能相加为整场改善。'))


def evaluate(m, task, root, config):
    m.gap_eval(task, root, config)
    directory = m.gap_setup(task, root, 'eval')
    cp = read(directory / 'checkpoints' / f'step_{STEPS:09d}.json')
    model = m.FullPPO.load(directory / 'checkpoints' / Path(cp['model']).name, device='cpu')
    with (directory / 'checkpoints' / Path(cp['vecnorm']).name).open('rb') as f: norm = pickle.load(f)
    norm.training = False; norm.norm_reward = False; model.policy.set_training_mode(False)
    def all_weights_sha():
        h = hashlib.sha256(m.policy_sha(model.policy).encode())
        for key,value in sorted(model.dispatch_value.state_dict().items()):
            h.update(key.encode());h.update(value.detach().cpu().numpy().tobytes())
        return h.hexdigest()
    before = all_weights_sha(); target = directory / 'NEW_ORDER_CONFIRMATION.json'
    if not target.exists():
        episodes = []
        for bank in config['sealed_bank']:
            os.environ['UAM_ATTR_TRACE_SHA'] = bank['sha256']
            cfg = dict(config, trace=bank['path'], _capture_lifecycle=True, _final_checkpoint=True)
            result = m.full_replay(model, norm, root, task, cfg, 123, True, probe=False)
            episodes.append(dict(result, trace=bank['name'], trace_sha256=bank['sha256']))
        save(target,dict(task=task,episodes=episodes,checkpoint=STEPS,
            scope='新增四条条件重排的最终固定存档确认，不按Best选择，不是新需求分布'))
    quality_eval(m, task, root, config, model, norm)
    if all_weights_sha() != before: raise RuntimeError('评估改变策略或条件头权重')
    save(directory / 'STAGE_EVAL_END.json',dict(step=STEPS,status='COMPLETE',weights_unchanged=True,
                                             actor_and_shadow_sha256=before,time=time.time()))


def aggregate(m, root, task_list):
    rows = []; status = []; initial = {}
    for task in task_list:
        folder = root / 'cells' / task['id']; train = read(folder/'TRAIN_END.json'); result = read(folder/'RESULT.json')
        evaluated = (folder/'STAGE_EVAL_END.json').is_file(); failures = list(folder.glob('FAILED_*.json'))
        live = read(folder/'LIVE.json',{})
        status.append(dict(**task,trained=bool(train),evaluated=evaluated,steps=train['steps'] if train else live.get('steps',0),
                           active_failure=bool(failures) and not evaluated,historical_failures=len(failures)))
        ini = read(folder/'INITIAL_POLICY_SHA.json')
        if ini and task['control']=='J3':
            family = 'PLAIN' if task['stin_mode']=='PLAIN' else 'AUTHOR_STIN'
            initial.setdefault((task['seed'],family),set()).add(ini['sha256'])
        if result:
            record = dict(**task,late_rpt=result['main_late_confirmation']['rpt'],final_rpt=result['final_confirmation']['rpt'],
                          late_completion=result['main_late_confirmation']['completion'],late_full=result['main_late_confirmation']['full_episode_fraction'])
            confirmation=read(folder/'NEW_ORDER_CONFIRMATION.json')
            if confirmation:
                record['new_order_rpt']=statistics.mean(e['restricted_person_time_per_generated'] for e in confirmation['episodes'])
                record['new_order_completion']=statistics.mean(e['completion'] for e in confirmation['episodes'])
            rows.append(record)
    if any(len(v)>1 for v in initial.values()): raise RuntimeError('同种子信用三臂或STIN开关的初始权重不一致')
    measured, upper = m.budget_account(root)
    p = dict(total=len(task_list),trained=sum(r['trained'] for r in status),evaluated=sum(r['evaluated'] for r in status),
        failed=sum(r['active_failure'] for r in status),historical_failures=sum(r['historical_failures'] for r in status),
        completed_training_transitions=sum(int(r['steps']) for r in status if r['trained']),
        measured_training_work=measured,interrupted_unlogged_upper_bound=upper,
        planned_actual_budget=PLANNED_STEPS,budget_cap=CAP,time=m.now())
    m.save_csv(root/'MODEL_RESULTS.csv',rows);m.save_csv(root/'RUN_STATUS.csv',status);save(root/'progress.json',p)
    pairs=[]
    by={(r['seed'],r['control'],r['arm']):r for r in rows}
    for seed in (1901,1902,1903,1904):
        for a,b in (('CONDITIONAL','SPLIT'),('STIN_OFF','STIN_ON'),('SPLIT','JOINT'),('CONDITIONAL','JOINT')):
            x,y=by.get((seed,'J3',a)),by.get((seed,'J3',b))
            if x and y:pairs.append(dict(seed=seed,contrast=a+'减'+b,late_delta=x['late_rpt']-y['late_rpt'],
                new_order_delta=x.get('new_order_rpt',float('nan'))-y.get('new_order_rpt',float('nan'))))
    m.save_csv(root/'PAIRED_EFFECTS.csv',pairs)
    return p


def child(phase, task, root, config, deadline):
    folder = root/'cells'/task['id'] if phase!='rules' else root/'rules'
    folder.mkdir(parents=True,exist_ok=True)
    if phase=='train' and (folder/'TRAIN_END.json').exists():return True
    if phase=='eval' and (folder/'STAGE_EVAL_END.json').exists():return True
    if phase=='rules' and (folder/'RULES_DONE.json').exists():return True
    if list(folder.glob('FAILED_'+phase+'_*.json')) and not config['retry_failed']:return False
    record=folder/('JOB_'+phase+'.json');save(record,dict(task=task,config=config))
    started=time.monotonic()
    with (folder/(phase+'.log')).open('a',encoding='utf-8') as log:
        process=subprocess.Popen([sys.executable,'-B','-u',str(Path(__file__).resolve()),'--worker',phase,
            '--task',str(record),'--root',str(root)],cwd=PROJECT,stdout=log,stderr=subprocess.STDOUT)
        while process.poll() is None:
            save(root/'RUNNING.json',dict(phase=phase,task=task,pid=process.pid,elapsed_seconds=time.monotonic()-started,
                                         worker_progress=read(folder/'LIVE.json',{}),time=time.time()))
            if time.monotonic()>deadline or (root/'STOP_REQUESTED').exists():
                process.terminate()
                try:process.wait(timeout=15)
                except subprocess.TimeoutExpired:process.kill();process.wait()
                save(folder/f'INTERRUPTED_{phase}_{time.time_ns()}.json',dict(reason='会话预算或停止请求',pid=process.pid,
                                                                 elapsed_seconds=time.monotonic()-started))
                return False
            time.sleep(2)
    if process.returncode:
        save(folder/f'FAILED_{phase}_{time.time_ns()}.json',dict(phase=phase,exit_code=process.returncode,
                    log=str(folder/(phase+'.log')),elapsed_seconds=time.monotonic()-started))
        return False
    return True


def take_lock(root):
    handle=(root/'PARENT.lock').open('a+b')
    if os.name=='nt':
        import msvcrt
        handle.seek(0)
        if not handle.read(1):handle.write(b'0');handle.flush()
        handle.seek(0);msvcrt.locking(handle.fileno(),msvcrt.LK_NBLCK,1)
    else:
        import fcntl
        fcntl.flock(handle.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
    return handle


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--resume',action='store_true');ap.add_argument('--retry-failed',action='store_true')
    ap.add_argument('--device',choices=('cpu','cuda'),default='cuda');ap.add_argument('--eval-device',choices=('cpu',),default='cpu')
    ap.add_argument('--wall-hours',type=float,default=18.);ap.add_argument('--min-free-gib',type=float,default=15.)
    ap.add_argument('--phase',choices=('all','train','eval','pack'),default='all')
    ap.add_argument('--plan',action='store_true');ap.add_argument('--root',type=Path)
    ap.add_argument('--worker',choices=('train','eval','rules'));ap.add_argument('--task',type=Path)
    args=ap.parse_args();task_list=tasks()
    if args.plan:
        print(json.dumps(dict(version=VERSION,tasks=task_list,actual_steps=PLANNED_STEPS,steps_per_model=STEPS,
            budget_cap=CAP,wall_hours=18,primary='CONDITIONAL vs SPLIT；公开源码STIN_OFF vs STIN_ON',
            source_fps=dict(joint_transformer=1305.6086,single_transformer=1460.6780),
            expected_hours='普通组按历史吞吐约8.08小时；STIN八格未实测，规划约4.2–5.4小时，加更新和评估约14–16小时；18小时上限，不补步数凑时长'),ensure_ascii=False,indent=2));return
    if not 0<args.wall_hours<=18:raise RuntimeError('本轮单会话最多18小时')
    root=args.root.resolve() if args.root else PROJECT/'serial_runs'/ROOT_NAME
    if root.name!=ROOT_NAME or root.parent!=(PROJECT/'serial_runs').resolve() or (args.root and args.root.is_symlink()):
        raise RuntimeError('输出只能是本项目新矩阵的独立目录')
    m=runtime()
    if args.worker:
        record=read(args.task);task,config=record['task'],record['config']
        if args.worker=='train':m.attr_train(task,root,config)
        elif args.worker=='eval':evaluate(m,task,root,config)
        else:
            m.gap_rules(task,root,dict(config,bank=config['bank']+config['sealed_bank']))
            save(root/'rules/RULES_DONE.json',dict(status='COMPLETE',time=time.time()))
        return
    root.mkdir(parents=True,exist_ok=True);lock=take_lock(root);started=time.monotonic();deadline=started+args.wall_hours*3600-90
    status='PARTIAL';reason=None
    try:
        previous=read(root/'SUITE_PLAN.json')
        if previous and previous['script_sha256']!=digest(__file__):raise RuntimeError('代码hash改变，不能混入旧矩阵')
        if previous and not args.resume and args.phase!='pack':raise RuntimeError('已有矩阵；使用--resume')
        if not previous and (root/'cells').exists() and any((root/'cells').iterdir()):raise RuntimeError('已有数据缺合同，保留待查')
        native=m.materialize_source(root);bank=m.gap_bank(root,native);sealed=make_confirmation_bank(m,root,native)
        config=dict(version=VERSION,device=args.device,eval_device='cpu',trace=str(native/'train_data/passengers_300.csv'),
            bank=bank,sealed_bank=sealed,train_horizon=500,eval_horizon=600,actual_steps=STEPS,requested_steps=STEPS,
            resume=args.resume,retry_failed=args.retry_failed,timeout_hours=3.)
        contract=dict(version=VERSION,script_sha256=digest(__file__),frozen_runtime_sha256=FROZEN_RUNTIME_SHA,
            tasks=task_list,config={k:v for k,v in config.items() if k not in ('resume','retry_failed')},
            planned_actual_budget=PLANNED_STEPS,budget_cap=CAP,
            frozen_stin_sha256=FROZEN_STIN_SHA,
            protocol='信用三臂同普通Transformer；STIN开关同初始参数与六帧输入；环境/奖励/profile固定',
            primary='后20%固定存档×4301–4304验证顺序；6501–6504只做最终固定存档确认')
        if previous and previous!=contract:raise RuntimeError('续跑的科学合同改变')
        if not previous:save(root/'SUITE_PLAN.json',contract)
        save(root/'TASK_REGISTRY.json',task_list)
        if args.phase=='pack':
            p=aggregate(m,root,task_list)
            if p['evaluated']==24 and not p['failed']:
                status='COMPLETE';m.gap_pack_models(root,task_list)
            m.attr_pack(root);return
        m.gap_resource_check(root,args.device,args.min_free_gib)
        rule_task=dict(task_list[-1],id='RULES__E1__K3',seed=0)
        if args.phase=='all':
            print('[规则基准] 同物理、验证及新确认顺序；不训练',flush=True)
            child('rules',rule_task,root,config,deadline)
        print('[预算]',PLANNED_STEPS,'/60,000,000；24格；每格',STEPS,'；18小时上限',flush=True)
        for i,task in enumerate(task_list,1):
            if time.monotonic()>=deadline or (root/'STOP_REQUESTED').exists():reason='本会话预算或停止请求';break
            m.gap_resource_check(root,args.device,args.min_free_gib)
            folder=root/'cells'/task['id']
            if args.phase in ('all','train'):
                print(f'[训练 {i}/24]',task['id'],flush=True)
                ok=child('train',task,root,config,deadline)
                if not ok:
                    aggregate(m,root,task_list)
                    if time.monotonic()>=deadline or (root/'STOP_REQUESTED').exists():reason='已保留恢复件';break
                    print('[单格失败保留，继续下一格]',task['id'],flush=True);continue
            if args.phase in ('all','eval') and (folder/'TRAIN_END.json').exists():
                print('[评估]',task['id'],flush=True);child('eval',task,root,config,deadline)
            aggregate(m,root,task_list)
        p=aggregate(m,root,task_list)
        rules_ok=(root/'rules/RULES_DONE.json').exists() or args.phase!='all'
        status='COMPLETE' if p['evaluated']==24 and not p['failed'] and rules_ok else 'PARTIAL'
        save(root/'END.json',dict(status=status,progress=p,wall_seconds=time.monotonic()-started,reason=reason,time=m.now(),
            note='训练回答有限预算下的估计器问题，不自动宣布交通创新；未完成不计为完整。'))
        if status=='COMPLETE':m.gap_pack_models(root,task_list)
        m.attr_pack(root)
    finally:
        save(root/'RUNNING.json',dict(phase='complete' if status=='COMPLETE' else 'idle_partial',pid=None,task=None,time=time.time()))
        lock.close()


if __name__=='__main__':main()
